  for(i=-R+1;i<R;i++)if(i&&i%2===0)g+=itT(X(i),c+13,i,9)+itT(c-8,Y(i)+3,i,9);
  (q.pt.show||[]).forEach(function(p){g+='<circle cx="'+X(p[1])+'" cy="'+Y(p[2])+'" r="4.5" fill="var(--ink)" stroke="none"/>'+itT(X(p[1])+10,Y(p[2])-6,p[0],12,'start')});
  if(rev)g+='<circle cx="'+X(q.pt.x)+'" cy="'+Y(q.pt.y)+'" r="7" fill="none" stroke="var(--ok)" stroke-width="3"/>';
